UPDATE businesses SET description = 'U-turn Charity Shop in Parow is part of U-Turn Homeless Ministries'' network of charity shops across Cape Town, selling secondhand clothing, household goods and furniture to the public. Proceeds from sales fund U-Turn''s programmes, which are built around equipping people experiencing homelessness with the skills and support needed to move off the streets long-term.

U-Turn was founded in 1997 and has grown into one of the city''s longer-running homelessness organisations, running its shops as a trading arm that generates income rather than relying solely on donations to fund its work. Shoppers at the Parow branch can expect the same rotating stock of donated clothing, furniture and household items typical of charity shops, with prices kept low to move stock regularly. Located on Voortrekker Road in Parow, Cape Town, the shop gives residents an affordable secondhand shopping option while supporting U-Turn''s homelessness programmes directly.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://homeless.org.za/charity-shops/', '$[#]', 'https://southernsuburbstatler.co.za/news/2022-11-03-u-turn-helping-the-homeless-for-25-years/'), description_enriched_at = datetime('now') WHERE slug = 'u-turn-charity-shop-parow' AND description = 'U-turn Charity Shop is part of U-Turn Homeless Ministries'' network of Cape Town charity shops, selling secondhand clothing, household goods and furniture to fund programmes equipping people to overcome homelessness. U-Turn was founded in 1997.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
